// Robust Normalization of incoming job payload
const raw = $input.first().json;
const job = raw.body?.job || raw.job || raw.body || raw;

const title = (job.title || 'Healthcare Professional Opening').trim();
const companyName = (job.companyName || 'Healthcare Provider').trim();
const category = (job.category || 'Healthcare').trim();
const location = (job.location || 'United States / Remote').trim();
const workplaceType = (job.workplaceType || 'Remote').trim();
const salaryString = (job.salaryString || '$90,000 - $140,000 / year').trim();
const applicationUrl = (job.applicationUrl || 'http://localhost:5174').trim();
const guid = job.guid || job.id || `gen-${Date.now()}`;
const credentials = Array.isArray(job.credentials) ? job.credentials : [];

return [{
  json: {
    guid,
    title,
    companyName,
    category,
    location,
    workplaceType,
    salaryString,
    applicationUrl,
    credentials,
    notificationTitle: `🚨 New Healthcare Opening: ${title} at ${companyName}`,
    timestamp: new Date().toISOString()
  }
}];

